async (page) => {
  await page.getByLabel('Rows per page').selectOption('50');
  const seen = new Map();
  for (let i=0;i<30;i++){
    const rows = await page.$$eval('tbody tr', trs=>trs.map(tr=>[...tr.cells].map(c=>c.innerText.trim())));
    rows.forEach(r=>seen.set(r[0]+r[1]+r[2],r));
    const next = page.getByRole('button',{name:'Next'});
    if (await next.isDisabled()) break;
    await next.click();
  }
  const all=[...seen.values()];
  const m=all.filter(r=>r[3]==='West'&&r[5]==='Refunded');
  const sum=m.reduce((s,r)=>s+Math.round(parseFloat(r[6].replace(/[$,]/g,''))*100),0);
  return {total:all.length, n:m.length, sum:sum/100, ids:m.map(r=>r[0]), regions:[...new Set(all.map(r=>r[3]))], st:[...new Set(all.map(r=>r[5]))]};
}

